'use strict';
// Explicit user file/recovery controls over the same persistence owner; no credentials or native methods.
(()=>{
 const store=window.OpenSesameWorkspaceData;if(!store||window.__OPEN_SESAME_PLATFORM__==='ios')return;
 const make=(tag,text)=>{const node=document.createElement(tag);if(text)node.textContent=text;return node};
 const open=make('button','Workspace data');open.id='workspace-data-open';open.type='button';open.className='plugin-secondary';open.setAttribute('aria-haspopup','dialog');
 const dialog=make('dialog');dialog.id='workspace-data-dialog';dialog.setAttribute('aria-labelledby','workspace-data-title');dialog.style.cssText='max-width:min(620px,calc(100vw - 32px));max-height:90dvh;overflow:auto;background:#202024;color:#eee;border:1px solid #555;border-radius:16px;padding:24px';
 const title=make('h2','Workspace data');title.id='workspace-data-title';const description=make('p','Export acknowledged workspace data or explicitly replace it from a validated file. Use open-draft recovery for text that could not be persisted. Credentials and companion authority are excluded. Replacement keeps the previous generation for recovery; reload afterward to use the new data.');
 const status=make('p');status.id='workspace-data-status';status.setAttribute('role','status');
 const actions=make('div');actions.style.cssText='display:flex;gap:12px;flex-wrap:wrap';
 const drafts=make('button','Export open drafts for recovery');drafts.type='button';drafts.className='plugin-secondary';
 const exportButton=make('button','Export saved workspace JSON'),restore=make('button','Restore previous generation'),close=make('button','Close'),reload=make('button','Reload workspace');
 for(const b of [exportButton,restore,close,reload,drafts]){b.type='button';b.className='plugin-secondary';b.style.cssText='color:#eee;background:#303036;border:1px solid #777;border-radius:8px;padding:10px;white-space:normal;max-width:100%'}reload.hidden=true;
 const label=make('label','Choose workspace JSON to preview: '),file=make('input');file.type='file';file.accept='.json,application/json';file.id='workspace-data-file';file.style.maxWidth='100%';label.append(file);
 const preview=make('p');preview.id='workspace-data-preview';const replace=make('button','Replace workspace with this file');replace.id='workspace-data-replace';replace.type='button';replace.disabled=true;replace.className='plugin-secondary';
 let selected=null,revision=null,busy=false;
 async function run(fn){if(busy)return;busy=true;for(const b of [exportButton,restore,replace])b.disabled=true;try{await fn()}catch(error){status.textContent=error.message+' Your saved originals and open drafts are preserved.'}finally{busy=false;if(store.status==='ready'){exportButton.disabled=restore.disabled=false;replace.disabled=!selected}}}
 function replaced(){store.retire();selected=null;replace.disabled=true;file.disabled=true;exportButton.disabled=restore.disabled=true;reload.hidden=false;status.textContent='Workspace generation committed. Reload to open it; the previous generation is retained.'}
 open.onclick=()=>{status.textContent=store.status==='ready'?'':'Storage needs reconciliation. Export open drafts before reloading the committed workspace.';reload.hidden=store.status==='ready';dialog.showModal()};close.onclick=()=>dialog.close();reload.onclick=()=>{if(store.status==='retired'||confirm('Reload the committed workspace? Export open drafts first if their save failed.'))location.reload()};
 exportButton.onclick=()=>run(async()=>{await store.flush();const text=store.exportJSON(),url=URL.createObjectURL(new Blob([text],{type:'application/json;charset=utf-8'})),a=make('a');a.href=url;a.download='open-sesame-workspace.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);status.textContent='Download requested. Check your browser’s downloads.'});
 file.onchange=()=>run(async()=>{selected=null;replace.disabled=true;const chosen=file.files?.[0];if(!chosen)return;if(chosen.size>OpenSesameWorkspaceStorageModel.MAX_BYTES)throw Error('The selected file exceeds the sixteen MiB limit.');const text=await chosen.text(),values=store.previewImport(text);await store.flush();revision=store.revision;selected=text;preview.textContent=Object.keys(values).length+' workspace sections validated. Replace will replace local workspace content, drafts and configuration. It cannot sign in, pair a companion or grant tool access.';status.textContent='Review the replacement, then choose Replace explicitly.'});
 replace.onclick=()=>run(async()=>{if(!selected)throw Error('Choose and preview a file first.');await store.importJSON(selected,{mode:'replace',expectedRevision:revision,retireAfter:true});replaced()});
 restore.onclick=()=>run(async()=>{if(!confirm('Restore the previous committed workspace generation? Current data is retained as the next recovery generation. Reload will be required.'))return;await store.flush();await store.restorePrevious({expectedRevision:store.revision,retireAfter:true});replaced()});
 dialog.addEventListener('close',()=>open.focus({preventScroll:true}));dialog.addEventListener('keydown',e=>e.stopPropagation());
 drafts.onclick=()=>{try{const snapshot=window.OpenSesameWorkspaceDrafts.snapshot();OpenSesameWorkspaceStorageModel.values({'open-sesame-tool-drafts-v1':JSON.stringify(snapshot)});const text=JSON.stringify({format:'open-sesame-draft-recovery',drafts:snapshot},null,2),url=URL.createObjectURL(new Blob([text],{type:'application/json'})),a=make('a');a.href=url;a.download='open-sesame-open-drafts.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);status.textContent='Draft recovery download requested. It contains your local text, not an authenticated session.'}catch(error){status.textContent=error.message}};
 actions.append(exportButton,drafts,restore,reload,close);dialog.append(title,description,status,actions,make('hr'),label,preview,replace);document.body.append(dialog);document.getElementById('pane-plugins').prepend(open);
})();
